    o.images = { normal: homeStr(l.images && l.images.normal), hover: homeStr(l.images && l.images.hover), pressed: homeStr(l.images && l.images.pressed), disabled: homeStr(l.images && l.images.disabled) };
    o.action = homeStr(l.action) || "none";
